/* Addressable Evidence visual language (straitjacket/docs/VISUAL-DESIGN.md):
   Square corners, 1px rules, semantic colour only, no gradients, no glow, no glass/blur. */
:root {
  --bg: #0D0F12;
  --ground: #15181D;
  --surface: #15181D;
  --surface2: #1C2026;
  --ink: #ECEAE3;
  --muted: #8D939A;
  --faint: #7D848D;
  --grid: #272C33;
  --blue: #6F96FF;
  --blue2: #263A68;
  --amber: #F0B429;
  --amber2: #58451D;
  --red: #FF7768;
  --red2: #542925;
  --green: #63D3A4;
  --panel: #15181D;

  --font-display: 'Space Grotesk Variable', 'Space Grotesk', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter Variable', 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  /* 3D subject placement beside the left panel (stage.js reads these on resize). */
  --frame-x: 0.21;
  --frame-y: -0.02;
  --frame-fit: 1.08;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--ink); }
body {
  font: 15px/1.55 var(--font-body);
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

/* Top instrument bar */
.hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  background: var(--bg);
  border-bottom: 1px solid var(--grid);
}
.hud-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: 44px;
  padding: 0 20px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
  white-space: nowrap;
}
.brand-mark {
  width: 10px;
  height: 10px;
  background: var(--amber);
  display: inline-block;
  flex-shrink: 0;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.1em;
}
.brand-ver {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--muted);
  padding: 2px 6px;
  border: 1px solid var(--grid);
  background: var(--surface);
}
.chapter-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.chapter-nav a {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--muted);
  padding: 6px 10px;
  border-bottom: 2px solid transparent;
  transition: color 0.15s ease, border-color 0.15s ease;
}
.chapter-nav a span { color: var(--faint); margin-right: 4px; }
.chapter-nav a:hover { color: var(--ink); }
.chapter-nav a.is-active {
  color: var(--ink);
  border-bottom-color: var(--amber);
}
.chapter-nav a.is-active span { color: var(--amber); }

.docs-link {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--ink);
  padding: 5px 12px;
  border: 1px solid var(--grid);
  background: var(--surface);
  white-space: nowrap;
}
.docs-link:hover { border-color: var(--blue); color: var(--blue); }

.progress-rail {
  height: 2px;
  width: 100%;
  background: var(--surface2);
}
.progress-fill {
  height: 100%;
  width: 0%;
  background: var(--blue);
  transform-origin: left center;
}

/* Canvas fixed behind chapters */
#stage { position: fixed; inset: 0; width: 100vw; height: 100vh; height: 100lvh; display: block; z-index: 0; }
.chapter { position: relative; z-index: 1; }

/* Film layout: strictly under .webgl-on */
.webgl-on .chapter { min-height: 220vh; }
.webgl-on .chapter:first-child { min-height: 190vh; }
.webgl-on .chapter[data-chapter="hosts"] { min-height: 240vh; }
.webgl-on .chapter:last-child { min-height: 220vh; }

.webgl-on .panel {
  position: fixed;
  top: 76px;
  left: 32px;
  width: min(30.5rem, 38vw);
  max-height: calc(100vh - 104px);
  overflow: auto;
  padding: 24px 26px;
  background: var(--panel);
  border: 1px solid var(--grid);
  border-top: 2px solid var(--grid);
  border-radius: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}
