const drawListeners = [];
function draw(T) {
  shown = T;
  dirty = false;
  const state = evaluate(T, ids);
  state.at = at;
  mark(T, state.moving);
  stage.render(state);
  for (const fn of drawListeners) fn(T, state.chapter, ids.length);
}
